import java.util.*;class Main{static void sort(int[] a,int l,int r){if(l>=r)return;int m=(l+r)/2;sort(a,l,m);sort(a,m+1,r);int[] temp=new int[r-l+1];int i=l,j=m+1,k=0;while(i<=m&&j<=r)temp[k++]=a[i]<=a[j]?a[i++]:a[j++];while(i<=m)temp[k++]=a[i++];while(j<=r)temp[k++]=a[j++];System.arraycopy(temp,0,a,l,temp.length);}public static void main(String[] args){int[] a={8,3,5,1,9};sort(a,0,a.length-1);System.out.println(Arrays.toString(a));}}
